<?php
require dirname(__DIR__) . '/config.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=$_POST['action']??'';if($a==='delete')db()->prepare('DELETE FROM skills WHERE id=?')->execute([(int)$_POST['id']]);else{$name=trim($_POST['name']??'');$level=max(0,min(100,(int)($_POST['level']??80)));$order=(int)($_POST['sort_order']??0);if($name!==''){if((int)($_POST['id']??0))db()->prepare('UPDATE skills SET name=?,level=?,sort_order=? WHERE id=?')->execute([$name,$level,$order,(int)$_POST['id']]);else db()->prepare('INSERT INTO skills(name,level,sort_order) VALUES(?,?,?)')->execute([$name,$level,$order]);}}flash('Skills updated.');redirect('admin/skills.php');}
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM skills WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$rows=db()->query('SELECT * FROM skills ORDER BY sort_order,id')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Skills</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body class="dashboard"><div class="admin-shell"><?php include 'nav.php';?><main class="admin-main"><div class="admin-top"><div><span class="eyebrow">PORTFOLIO CONTENT</span><h1>Skills</h1></div></div><?php show_flash();?><div class="admin-panel mb-4"><h2><?=$edit?'Edit skill':'Add a skill'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="row g-3"><div class="col-md-5"><label>Skill name</label><input class="form-control" name="name" required value="<?=e($edit['name']??'')?>"></div><div class="col-md-3"><label>Proficiency (0–100)</label><input class="form-control" type="number" min="0" max="100" name="level" value="<?=(int)($edit['level']??80)?>"></div><div class="col-md-2"><label>Order</label><input class="form-control" type="number" name="sort_order" value="<?=(int)($edit['sort_order']??0)?>"></div><div class="col-12"><button class="btn btn-primary">Save skill</button><?php if($edit):?> <a href="skills.php" class="btn btn-outline-light">Cancel</a><?php endif;?></div></div></form></div><div class="admin-panel"><h2>Current skills</h2><div class="table-responsive"><table class="table table-dark"><thead><tr><th>Skill</th><th>Level</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=$r['level']?>%</td><td><a href="?edit=<?=$r['id']?>">Edit</a><form class="d-inline" method="post" onsubmit="return confirm('Delete skill?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-link text-danger p-0 ms-2">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></main></div></body></html>
